import sys

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    suffixes = set()

    for i in range(5, n):
        if i - 2 >= 5:
            suffixes.add(s[i-2:i])
        if i - 3 >= 5:
            suffixes.add(s[i-3:i])

    suffixes = sorted(suffixes)
    print(len(suffixes))
    for suffix in suffixes:
        print(suffix)

main()
